CREATE TABLE IF NOT EXISTS orders (id CHAR(36) PRIMARY KEY, order_number VARCHAR(20), customer_name VARCHAR(100), customer_email VARCHAR(255), customer_phone VARCHAR(30), address_line VARCHAR(200), city VARCHAR(100), postal_code VARCHAR(20), country VARCHAR(100), notes TEXT, subtotal DECIMAL(10,2), discount DECIMAL(10,2), shipping_method VARCHAR(30), shipping_fee DECIMAL(10,2), total DECIMAL(10,2), payment_method VARCHAR(10), payment_status VARCHAR(30), payment_ref VARCHAR(64), status VARCHAR(20), created_at VARCHAR(40), updated_at VARCHAR(40)) CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS order_items (id CHAR(36) PRIMARY KEY, order_id CHAR(36), product_id CHAR(36), product_name VARCHAR(200), size VARCHAR(20), quantity INT, unit_price DECIMAL(10,2), created_at VARCHAR(40), INDEX(order_id)) CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (id CHAR(36) PRIMARY KEY, name VARCHAR(200), slug VARCHAR(200), price DECIMAL(10,2), compare_at_price DECIMAL(10,2), stock INT, category VARCHAR(50), is_active TINYINT, featured TINYINT, image_url TEXT, updated_at VARCHAR(40)) CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS sync_state (k VARCHAR(20) PRIMARY KEY, v VARCHAR(40)) CHARSET=utf8mb4;
